def cov_model(cx,cy,w,r,px,py,N=512,curve=None):
    hw=w/2.0; cnt=0
    pts=[]
    if curve=='quad':
        # quadratic bezier from (cx,cy-hw) to (cx-hw,cy) ctrl (cx,cy)
        # wait orientation: outer endpoints (cx, cy-hw)?? For TL corner: horiz arm outer edge y=cy-hw ending at x=cx; vert arm outer edge x=cx-hw ending at y=cy
        P0=(cx,cy-hw); C=(cx,cy); P1=(cx-hw,cy)
        M=64
        for k in range(M+1):
            t=k/M
            x=(1-t)**2*P0[0]+2*(1-t)*t*C[0]+t*t*P1[0]
            y=(1-t)**2*P0[1]+2*(1-t)*t*C[1]+t*t*P1[1]
            pts.append((x,y))
    def in_curve(x,y):
        # point inside if "below-right" of polyline pts (curve from top to left)
        # find max x on curve at this y
        for k in range(len(pts)-1):
            (x0,y0),(x1,y1)=pts[k],pts[k+1]
            if (y0-y)*(y1-y)<=0 and y0!=y1:
                xi=x0+(x1-x0)*(y-y0)/(y1-y0)
                return x>=xi
        return False
    for i in range(N):
        for j in range(N):
            x=px+(i+0.5)/N; y=py+(j+0.5)/N
            ins=False
            if abs(y-cy)<=hw and x>=cx: ins=True
            if abs(x-cx)<=hw and y>=cy: ins=True
            if r is not None and (x-cx)**2+(y-cy)**2<=r*r: ins=True
            if curve=='quad' and x<=cx and y<=cy and x>=cx-hw and y>=cy-hw:
                # inside the rounded triangle region if below-right of curve
                if in_curve(x,y): ins=True
            if ins: cnt+=1
    return cnt/(N*N)

